-- Module: timetable — Timetable

CREATE SCHEMA IF NOT EXISTS timetable;
COMMENT ON SCHEMA timetable IS 'Timetable: Period definitions and scheduled teaching sessions.';

CREATE TABLE timetable.period (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid NOT NULL,
    name varchar(60) NOT NULL,
    start_time time NOT NULL,
    duration_minutes numeric(6,2),
    sequence integer,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_period PRIMARY KEY (id),
    CONSTRAINT ck_period_duration_minutes_rule CHECK (duration_minutes>0),
    CONSTRAINT uq_period_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE timetable.period IS 'Named teaching period with a start time and duration.';
COMMENT ON COLUMN timetable.period.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN timetable.period.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN timetable.period.institution_id IS 'Institution.';
COMMENT ON COLUMN timetable.period.name IS 'Period name.';
COMMENT ON COLUMN timetable.period.start_time IS 'Start time.';
COMMENT ON COLUMN timetable.period.duration_minutes IS 'Duration in minutes.';
COMMENT ON COLUMN timetable.period.sequence IS 'Order in the day.';
COMMENT ON COLUMN timetable.period.created_at IS 'Row creation time.';
COMMENT ON COLUMN timetable.period.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN timetable.period.updated_at IS 'Last update time.';
COMMENT ON COLUMN timetable.period.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN timetable.period.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN timetable.period.row_version IS 'Optimistic-locking version.';

CREATE TABLE timetable.session (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid NOT NULL,
    period_id uuid,
    start_at timestamptz NOT NULL,
    end_at timestamptz NOT NULL,
    weekday smallint,
    class_section_id uuid,
    course_id uuid,
    batch_id uuid,
    subject_id uuid,
    staff_id uuid,
    room_id uuid,
    title varchar(150),
    session_type varchar(30),
    color smallint,
    status varchar(30) NOT NULL DEFAULT  'draft',
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_session PRIMARY KEY (id),
    CONSTRAINT ck_session_weekday_rule CHECK (weekday BETWEEN 1 AND 7),
    CONSTRAINT ck_session_status CHECK (status IN ('draft', 'confirmed', 'done', 'cancelled')),
    CONSTRAINT ck_session_1 CHECK (end_at > start_at),
    CONSTRAINT ck_session_2 CHECK (class_section_id IS NOT NULL OR (course_id IS NOT NULL AND batch_id IS NOT NULL)),
    CONSTRAINT uq_session_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE timetable.session IS 'Scheduled teaching session (one class meeting).';
COMMENT ON COLUMN timetable.session.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN timetable.session.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN timetable.session.institution_id IS 'Institution.';
COMMENT ON COLUMN timetable.session.period_id IS 'Period.';
COMMENT ON COLUMN timetable.session.start_at IS 'Start.';
COMMENT ON COLUMN timetable.session.end_at IS 'End.';
COMMENT ON COLUMN timetable.session.weekday IS 'ISO weekday (1 = Monday).';
COMMENT ON COLUMN timetable.session.class_section_id IS 'Class section (K-12).';
COMMENT ON COLUMN timetable.session.course_id IS 'Course (higher education).';
COMMENT ON COLUMN timetable.session.batch_id IS 'Batch (higher education).';
COMMENT ON COLUMN timetable.session.subject_id IS 'Subject taught (NULL for breaks, events and exam slots).';
COMMENT ON COLUMN timetable.session.staff_id IS 'Staff member taking the session (NULL for breaks and events).';
COMMENT ON COLUMN timetable.session.room_id IS 'Room.';
COMMENT ON COLUMN timetable.session.title IS 'Display title.';
COMMENT ON COLUMN timetable.session.session_type IS 'Session type (lecture, lab, tutorial...).';
COMMENT ON COLUMN timetable.session.color IS 'Calendar colour index.';
COMMENT ON COLUMN timetable.session.status IS 'Session state.';
COMMENT ON COLUMN timetable.session.created_at IS 'Row creation time.';
COMMENT ON COLUMN timetable.session.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN timetable.session.updated_at IS 'Last update time.';
COMMENT ON COLUMN timetable.session.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN timetable.session.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN timetable.session.row_version IS 'Optimistic-locking version.';
-- timetable.GetTimetable reads the sessions of one teacher, class, batch or room over a range of days, in start order:
-- each index leads with the subject of the view and ends with the start, so a week is one short index range.
CREATE INDEX ix_session_staff_start ON timetable.session (tenant_id, staff_id, start_at) WHERE deleted_at IS NULL AND staff_id IS NOT NULL;
CREATE INDEX ix_session_class_section_start ON timetable.session (tenant_id, class_section_id, start_at) WHERE deleted_at IS NULL AND class_section_id IS NOT NULL;
CREATE INDEX ix_session_batch_start ON timetable.session (tenant_id, batch_id, start_at) WHERE deleted_at IS NULL AND batch_id IS NOT NULL;
CREATE INDEX ix_session_room_start ON timetable.session (tenant_id, room_id, start_at) WHERE deleted_at IS NULL AND room_id IS NOT NULL;

CREATE TABLE timetable.session_student (
