    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_session_student PRIMARY KEY (id)
);
COMMENT ON TABLE timetable.session_student IS 'Students expected in a session (for split groups / electives).';
COMMENT ON COLUMN timetable.session_student.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN timetable.session_student.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN timetable.session_student.session_id IS 'Session.';
COMMENT ON COLUMN timetable.session_student.student_id IS 'Student.';
COMMENT ON COLUMN timetable.session_student.created_at IS 'Row creation time.';
COMMENT ON COLUMN timetable.session_student.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN timetable.session_student.updated_at IS 'Last update time.';
COMMENT ON COLUMN timetable.session_student.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN timetable.session_student.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN timetable.session_student.row_version IS 'Optimistic-locking version.';

-- Intra-module foreign keys
ALTER TABLE timetable.session ADD CONSTRAINT fk_session_period_id FOREIGN KEY (period_id, tenant_id) REFERENCES timetable.period (id, tenant_id) ON DELETE SET NULL (period_id);
CREATE INDEX ix_session_period_id ON timetable.session (period_id);
ALTER TABLE timetable.session_student ADD CONSTRAINT fk_session_student_session_id FOREIGN KEY (session_id, tenant_id) REFERENCES timetable.session (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_session_student_session_id ON timetable.session_student (session_id);

-- === P1-12: sync/retention indexes ===

CREATE INDEX ix_session_tenant_updated_at ON timetable.session (tenant_id, updated_at);

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE timetable.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    publish_error text,
    CONSTRAINT pk_timetable_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE timetable.outbox_event IS 'Transactional outbox of the timetable module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN timetable.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN timetable.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN timetable.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN timetable.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN timetable.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN timetable.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN timetable.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN timetable.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
COMMENT ON COLUMN timetable.outbox_event.publish_error IS 'Why the relay could not turn the row into an event (set aside, not published); NULL otherwise.';
CREATE INDEX ix_timetable_outbox_event_pending ON timetable.outbox_event (id) WHERE published_at IS NULL AND publish_error IS NULL;
CREATE TABLE timetable.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_timetable_inbox_event PRIMARY KEY (tenant_id, event_id)
);
COMMENT ON TABLE timetable.inbox_event IS 'Inbox of the timetable module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN timetable.inbox_event.event_id IS 'Global id of the consumed event; recorded per tenant.';
COMMENT ON COLUMN timetable.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN timetable.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN timetable.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN timetable.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN timetable.inbox_event.processing_error IS 'Last handling error, if any.';
CREATE INDEX ix_timetable_inbox_event_processed ON timetable.inbox_event (processed_at) WHERE processed_at IS NOT NULL;

