CREATE UNIQUE INDEX uq_period_1 ON timetable.period (institution_id, name) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_session_student_1 ON timetable.session_student (session_id, student_id) WHERE deleted_at IS NULL;

-- === P0-03: row-level security (tenant isolation). The application role is not the table owner and sets app.tenant_id per transaction; a platform-admin role with BYPASSRLS serves cross-tenant operations ===

ALTER TABLE timetable.inbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE timetable.inbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON timetable.inbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE timetable.outbox_event ENABLE ROW LEVEL SECURITY;
